  | _, _ => false
  end.
Definition ft_ieq4 (a0 a1 a2 a3 b0 b1 b2 b3 : Z) : bool :=
  Z.land (Z.lxor (u32le a0 a1 a2 a3) (u32le b0 b1 b2 b3)) 0xDFDFDFDF =? 0.

Lemma ft_ieqb_length : forall a b, ft_ieqb a b = true -> length a = length b.
Proof.
  induction a as [|x a IH]; intros [|y b] H; cbn in H |- *; try discriminate; [reflexivity|].
  apply andb_prop in H. f_equal. apply IH. tauto.
Qed.

