Lemma ft_slot_range : forall i, 0 <= ft_slot i < 1367.
Proof. intros i. unfold ft_slot. apply Z.mod_pos_bound. lia. Qed.

(* [comment removed for export] *)
Lemma FT_MAP_range : Forall (fun v => 0 <= v < 130) FT_MAP.
Proof.
  assert (forallb (fun v => (0 <=? v) && (v <? 130)) FT_MAP = true) as H by (vm_compute; reflexivity).
  rewrite forallb_forall in H. apply Forall_forall. intros v Hv. specialize (H v Hv).
  apply andb_prop in H. destruct H as [H1 H2]. apply Z.leb_le in H1. apply Z.ltb_lt in H2. lia.
Qed.
Lemma FT_MAP_nth_range : forall j, 0 <= nth j FT_MAP 0 < 130.
Proof.
  intros j. destruct (Nat.lt_ge_cases j (length FT_MAP)) as [L|G].
  - apply (Forall_nth (fun v => 0 <= v < 130) FT_MAP); [apply FT_MAP_range | exact L].
  - rewrite nth_overflow by lia. lia.
Qed.

(* [comment removed for export] *)
Lemma ft_len_name : forallb (fun i : nat => (ft_len i =? Z.of_nat (length (ft_name i))) && (ft_len i <=? 35)) (seq 0 130) = true.
Proof. vm_compute. reflexivity. Qed.
Lemma ft_len_ok : forall i, (i < 130)%nat -> ft_len i = Z.of_nat (length (ft_name i)) /\ ft_len i <= 35.
Proof.
  intros i Hi. pose proof ft_len_name as F. rewrite forallb_forall in F.
  specialize (F i ltac:(apply in_seq; lia)). apply andb_prop in F. destruct F as [F1 F2].
  apply Z.eqb_eq in F1. apply Z.leb_le in F2. lia.
Qed.

(* [comment removed for export] *)
Definition ft_lookup (s : list Z) : Z :=
  let i := nth (Z.to_nat (ft_digest s mod 1367)) FT_MAP 0 in
  if i =? 0 then 0 else if ft_ieqb s (ft_name (Z.to_nat i)) then i else 0.

Lemma ft_lookup_range : forall s, 0 <= ft_lookup s < 130.
Proof.
  intros s. unfold ft_lookup. pose proof (FT_MAP_nth_range (Z.to_nat (ft_digest s mod 1367))).
  destruct (_ =? 0); [lia|]. destruct (ft_ieqb _ _); lia.
Qed.

(* [comment removed for export] *)
Lemma ft_dig1_range : forall bs r, 0 <= r < 2^32 -> 0 <= ft_dig1 r bs < 2^32.
Proof. induction bs as [|b bs IH]; intros r Hr; cbn [ft_dig1]; [lia|]. apply IH. apply Z.mod_pos_bound. lia. Qed.

