(* [comment removed for export] *)
Definition FT_TAB_BYTES : list byte := flat_map le8z ft_words.            (* [comment removed for export] *)
Definition FT_MAP_BYTES : list byte := map b8 FT_MAP.                       (* [comment removed for export] *)
Definition ft_nameb (i : nat) : list byte := map b8 (ft_name i).

Lemma FT_TAB_BYTES_length : length FT_TAB_BYTES = 2080%nat. Proof. reflexivity. Qed.
Lemma FT_MAP_BYTES_length : length FT_MAP_BYTES = 1367%nat. Proof. reflexivity. Qed.

Section HCW.
  Context {HCEIL : HeapCeil}.

(* [comment removed for export] *)
Definition FTCells : list cell := [CB 2080 FT_TAB_BYTES; CB 1367 FT_MAP_BYTES; CB 1 (zeros 1)].
Definition FTGuardCells : list cell := [CB 8 (b8 1 :: b8 1 :: zeros 6)].
Definition FT (m : mem) : Prop :=
  rw_cells bsegs m AG_FIELD_TABLE FTCells /\ rw_cells bsegs m AG_FIELD_TABLE_GUARD FTGuardCells.

