Lemma FTInit_transport : forall W m m',
  FTInit m -> munch W m m' -> disjoint_from W P_A_FT_INIT 2080 -> FTInit m'.
Proof.
  intros W m m' FI MU D. unfold FTInit in *. eapply bytes_at_transport; [exact FI | exact MU |].
  rewrite FT_TAB_BYTES_length. exact D.
Qed.

