Lemma ft_nameb_length : forall i, length (ft_nameb i) = length (ft_name i).
Proof. intros i. unfold ft_nameb. apply length_map. Qed.

(* [comment removed for export] *)
Lemma ft_ptr_range : forall i, (i < 130)%nat -> 0x275a0 <= ft_ptr i /\ ft_ptr i + ft_len i <= 0x28c10.
Proof.
  intros i Hi.
  assert (G : forallb (fun i : nat => (0x275a0 <=? ft_ptr i) && (ft_ptr i + ft_len i <=? 0x28c10)) (seq 0 130) = true) by (vm_compute; reflexivity).
  rewrite forallb_forall in G. specialize (G i ltac:(apply in_seq; lia)). apply andb_prop in G. destruct G as [G1 G2].
  apply Z.leb_le in G1. apply Z.leb_le in G2. lia.
Qed.

(* [comment removed for export] *)
Lemma zbytes_ft_nameb : forall i, zbytes (ft_nameb i) = ft_name i.
Proof.
  intros i. destruct (Nat.lt_ge_cases i 130) as [L|G].
  - assert (C : forallb (fun i : nat => if list_eq_dec Z.eq_dec (zbytes (ft_nameb i)) (ft_name i) then true else false) (seq 0 130) = true)
      by (vm_compute; reflexivity).
    rewrite forallb_forall in C. specialize (C i ltac:(apply in_seq; lia)).
    destruct (list_eq_dec Z.eq_dec (zbytes (ft_nameb i)) (ft_name i)) as [E|NE]; [exact E | discriminate].
  - unfold ft_nameb, ft_name. rewrite nth_overflow by (rewrite FT_NAMES_length; lia). reflexivity.
Qed.

