Proof. ltac2:(KReplay.run [|constr:(@Corelib.Init.Logic.eq_refl); constr:(@Corelib.Init.Datatypes.bool); constr:(@Corelib.Init.Datatypes.true); constr:(@Corelib.Init.Logic.eq); constr:(@Stdlib.Lists.List.forallb); constr:(@Corelib.Init.Datatypes.nat); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Bo.AsImgSh.aglobb); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Bo.X8_P_ftab_rep.ft_ptr); constr:(@OSSVerify.Proofs.boost_beast.http_request.lib.Bo.X8_P_ftab_rep.ft_len); constr:(@Corelib.Lists.ListDef.seq); constr:(@Corelib.Init.Datatypes.O); constr:(@Corelib.Init.Datatypes.S)|] [|@i|] "#$R#$#0#(#)###,#1#'#.#/#-#0#+#*#2$#/$VHCDUIEUJEVK$#j#$F##G##################################################################################################################################################################################################################################################################VLG#WMFs$*#WNC#Dm$s$0##"). Qed.
Lemma ft_name_accessible : forall m i, ACONST m -> (i < 130)%nat -> accessible m (ft_ptr i) (ft_len i).
Proof.
  intros m i AC Hi. pose proof ft_names_glob as F. rewrite forallb_forall in F.
  apply (ACONST_gbody_accessible m _ _ AC). apply F. apply in_seq. lia.
Qed.
Lemma ft_name_shvis : forall m i, ACONST m -> (i < 130)%nat -> shvis m (ft_ptr i) (ft_ptr i + ft_len i).
Proof.
  intros m i AC Hi. pose proof (ft_ptr_range i Hi) as [R1 R2]. pose proof (ft_len_ok i Hi) as [L1 L2].
  apply ACONST_img_shvis; [exact AC| | |]; unfold AIMG_LO, AIMG_TOP; lia.
Qed.
Lemma ft_name_in_app_mem : forall i, (i < 130)%nat -> in_app_mem (ft_ptr i) (ft_ptr i + ft_len i).
Proof.
  intros i Hi. pose proof (ft_ptr_range i Hi) as [R1 R2]. pose proof (ft_len_ok i Hi) as [L1 L2].
  apply img_in_app_mem; unfold AIMG_LO, AIMG_TOP; lia.
Qed.

